(startTime, duration, blocked) => {
  const time = String(startTime ?? "").trim();
  const raw = String(duration ?? "").trim();
  const minutes = Number(raw);
  const result = (available, reasonCode, message) => ({
    available,
    reasonCode,
    message
  });
  if (!(/^([01]\d|2[0-3]):[0-5]\d$/).test(time)) {
    return result(false, "invalid-time", "Validation error: Enter a valid HH:MM time.");
  }
  if (!raw || !Number.isInteger(minutes) || minutes <= 0) {
    return result(false, "invalid-time", "Validation error: Duration must be a positive whole number.");
  }
  const [h, m] = time.split(":").map(Number);
  const start = h * 60 + m;
  const end = start + minutes;
  if (start <= 540) {
    return result(false, "past-request", "Validation error: Start time must be after 09:00.");
  }
  if (minutes > 120) {
    return result(false, "too-long", "Validation error: Maximum duration is 120 minutes.");
  }
  if (end > 1440) {
    return result(false, "invalid-time", "Validation error: Interval exceeds the end of the day.");
  }
  if (blocked) {
    return result(false, "blocked", "Unavailable: Room A-101 is blocked.");
  }
  const overlap = Availability.bookings.some(b => start < b.end && end > b.start);
  if (overlap) {
    return result(false, "overlapping", "Unavailable: Overlaps with booking 10:00–11:00.");
  }
  return result(true, "available", `Available: Room A-101 is free from ${time} for ${minutes} minutes.`);
}

